-- Speglar det som lades på databasen 2026-09-15 via apply_migration i tre delar:
--   cm2_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   cm2_order_code_from_catalogue_part_02  (värdelista)
--   cm2_order_code_from_catalogue_part_03  (34 regler, dokumentkarta, produktspecar)
-- Katalogen smc-kat-cm2-z1.pdf (502 stycken) lästes in med scripts/ingest-catalogues.py
-- via de tillfälliga laddfunktionerna, som släpptes direkt efteråt.
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts cm2):
--   regler  34   md5 e4260afa79ebf03bd8d2b744743e8f7d   villkor a1d60d3ac6d4d0d31f37aacf9bb59928
--   värden  69   md5 8d7ef6dc577a05db854befcc6212f8e4
--   schema       md5 f9feebeab2ea984830ec35b30513f364
-- Verifierat live: /sv/configurator/cm2 bygger CDM2C20-50Z1-NV-M9BW (beställningsexemplet, sida 6).
--
-- CM2: beställnyckeln enligt SMC Air Cylinder CM2 Series (CM2-Z1).
-- GENERERAD ur src/lib/catalog/cm2.ts -- redigera inte för hand.
--
-- Rättar familjen cm2, som hade mallen 'CM2-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'.
-- SMC:s kod (Z1, sida 5) är
-- C{magnet}M2{fäste}{ø}{gänga}-{slag}{dämpning}{stångände}{bälg}Z1-{pivot}{tillbehör}-{givare}{kabel}{antal}-{special},
-- t.ex. CDM2C20-50Z1-NV-M9BW (sida 6). Fäste, portgänga, honstång, bälg,
-- pivotfäste och kolvstångstillbehör fanns inte alls.
--
-- Modellen är CM2-Z1: CM2-Z:s standardcylinder utgick i november 2025
-- (smc-kat-cm2.pdf sida 234). Katalogen smc-kat-cm2-z1.pdf hämtades och
-- lästes in 2026-09-15 (502 stycken).

begin;

create schema if not exists backup;
create table if not exists backup.cm2_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cm2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cm2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'cm2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-CM2-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"20","label":"ø20 mm"},{"v":"25","label":"ø25 mm"},{"v":"32","label":"ø32 mm"},{"v":"40","label":"ø40 mm"}]},{"id":"mounting","step":2,"title_sv":"Fäste","title_en":"Mounting","required":true,"type":"single_select","options":[{"v":"B","label":"Basutförande (dubbelsidig gänghals)"},{"v":"L","label":"Axiellt fotfäste"},{"v":"F","label":"Fläns vid kolvstången"},{"v":"G","label":"Fläns vid gaveln"},{"v":"C","label":"Enkelt gaffelfäste"},{"v":"D","label":"Dubbelt gaffelfäste"},{"v":"U","label":"Tappfäste vid kolvstången"},{"v":"T","label":"Tappfäste vid gaveln"},{"v":"E","label":"Integrerat gaffelfäste"},{"v":"V","label":"Integrerat gaffelfäste, 90°"},{"v":"BZ","label":"Boss-cut, basutförande"},{"v":"FZ","label":"Boss-cut, fläns vid kolvstången"},{"v":"UZ","label":"Boss-cut, tappfäste vid kolvstången"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":5,"max":2000,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (CDM2)"}]},{"id":"port","step":5,"title_sv":"Portgänga","title_en":"Port thread type","required":false,"type":"single_select","options":[{"v":"TN","label":"Portgänga NPT (standard är Rc)"},{"v":"TF","label":"Portgänga G (standard är Rc)"}]},{"id":"cushion","step":6,"title_sv":"Dämpning","title_en":"Cushion","required":false,"type":"single_select","options":[{"v":"A","label":"Luftdämpning (standard är gummidämpning)"}]},{"id":"rod_thread","step":7,"title_sv":"Kolvstångsände","title_en":"Rod end thread","required":false,"type":"single_select","options":[{"v":"F","label":"Honstång (invändig gänga; utan bälg och tillbehör)"}]},{"id":"boot","step":8,"title_sv":"Kolvstångsbälg","title_en":"Rod boot","required":false,"type":"single_select","options":[{"v":"J","label":"Bälg i nylonduk, max 70 °C"},{"v":"K","label":"Värmebeständig bälg, max 110 °C"}]},{"id":"pivot","step":9,"title_sv":"Pivotfäste","title_en":"Pivot bracket","required":false,"type":"single_select","options":[{"v":"N","label":"Pivotfäste medlevererat (bara fäste C, T, U, E, V, UZ)"}]},{"id":"rod_end","step":10,"title_sv":"Kolvstångstillbehör","title_en":"Rod end bracket","required":false,"type":"single_select","options":[{"v":"V","label":"Enkel knäled (utan sprint)"},{"v":"W","label":"Dubbel knäled"},{"v":"Q","label":"Kolvstångsände (rod end)"}]},{"id":"switch","step":11,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN, rak"},{"v":"M9P","label":"D-M9P, 3-tråd PNP, rak"},{"v":"M9B","label":"D-M9B, 2-tråd, rak"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinklad"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak"},{"v":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad"},{"v":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät, rak"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät, rak"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak"},{"v":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad"},{"v":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad"},{"v":"A96","label":"D-A96, reed 3-tråd, rak"},{"v":"A96V","label":"D-A96V, reed 3-tråd, vinklad"},{"v":"A93","label":"D-A93, reed 2-tråd, rak"},{"v":"A93V","label":"D-A93V, reed 2-tråd, vinklad"},{"v":"A90","label":"D-A90, reed utan indikering, rak"},{"v":"A90V","label":"D-A90V, reed utan indikering, vinklad"}]},{"id":"lead","step":12,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":13,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"1 givare (standard är 2)"}]},{"id":"mto","step":14,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (utan givare)"},{"v":"XB7","label":"-XB7 Köldbeständig –40…70 °C (utan givare, gummidämpning)"},{"v":"XB9","label":"-XB9 Låg hastighet 10–50 mm/s (gummidämpning; luft på begäran)"},{"v":"XC3","label":"-XC3 Speciell portplacering"},{"v":"XC4A","label":"-XC4A Dammtålig med två smörjhållare (gummidämpning, utan bälg)"},{"v":"XC4B","label":"-XC4B Dammtålig med smörjhållare och kraftig avstrykare (gummidämpning, utan bälg)"},{"v":"XC4C","label":"-XC4C Dammtålig med kraftig avstrykare (utan bälg)"},{"v":"XC6A","label":"-XC6A Rostfri kolvstång och stångmutter (slag ≤ 1000)"},{"v":"XC6B","label":"-XC6B Rostfri kolvstång, muttrar, låsring och fäste (slag ≤ 1000; ej gaffel-/tappfäste)"},{"v":"XC29","label":"-XC29 Dubbel knäled med fjädersprint (kräver tillbehör W)"},{"v":"XC52","label":"-XC52 Fästmutter med stoppskruv (fäste B, L, F, G, BZ, FZ)"},{"v":"XC85","label":"-XC85 Fett för livsmedelsindustrin"},{"v":"X446","label":"-X446 PTFE-fett"}]}]}'::jsonb,
        'SMC CM2 rundcylinder (Z1)', 'SMC CM2 round cylinder (Z1)', 'cylinder')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Rundcylinder ø20–40, dubbelverkande enkel kolvstång (CM2-Z1)',
  description = 'SMC CM2-Z1 round air cylinder, double acting single rod, ø20/25/32/40 mm, standard strokes 25–300 mm, 13 mounting styles.',
  stroke_min_mm = 5,
  stroke_max_mm = 2000,
  order_code_template = 'C{magnet}M2{mounting}{bore}{port}-{stroke_mm}{cushion}{rod_thread}{boot}Z1-{pivot}{rod_end}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-CM2-V1'
where slug = 'cm2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'cm2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'cm2';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"bore","label":"Kolvdiameter","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"mounting","label":"Fäste","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":3,"required":true,"min_value":5,"max_value":2000},{"param_key":"magnet","label":"Inbyggd magnet","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"port","label":"Portgänga","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"cushion","label":"Dämpning","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"rod_thread","label":"Kolvstångsände","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"boot","label":"Kolvstångsbälg","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"pivot","label":"Pivotfäste","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"rod_end","label":"Kolvstångstillbehör","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"switch","label":"Magnetgivare","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Givarens kabellängd","param_type":"select","sort_order":12,"required":false,"min_value":null,"max_value":null},{"param_key":"count","label":"Antal givare","param_type":"select","sort_order":13,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande","param_type":"select","sort_order":14,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'cm2';

insert into configurator_param_values (param_id, code, label, sort_order)
