from jsonb_to_recordset('[{"param_key":"bore","code":"20","label":"ø20 mm","sort_order":0},{"param_key":"bore","code":"25","label":"ø25 mm","sort_order":1},{"param_key":"bore","code":"32","label":"ø32 mm","sort_order":2},{"param_key":"bore","code":"40","label":"ø40 mm","sort_order":3},{"param_key":"mounting","code":"B","label":"Basutförande (dubbelsidig gänghals)","sort_order":0},{"param_key":"mounting","code":"L","label":"Axiellt fotfäste","sort_order":1},{"param_key":"mounting","code":"F","label":"Fläns vid kolvstången","sort_order":2},{"param_key":"mounting","code":"G","label":"Fläns vid gaveln","sort_order":3},{"param_key":"mounting","code":"C","label":"Enkelt gaffelfäste","sort_order":4},{"param_key":"mounting","code":"D","label":"Dubbelt gaffelfäste","sort_order":5},{"param_key":"mounting","code":"U","label":"Tappfäste vid kolvstången","sort_order":6},{"param_key":"mounting","code":"T","label":"Tappfäste vid gaveln","sort_order":7},{"param_key":"mounting","code":"E","label":"Integrerat gaffelfäste","sort_order":8},{"param_key":"mounting","code":"V","label":"Integrerat gaffelfäste, 90°","sort_order":9},{"param_key":"mounting","code":"BZ","label":"Boss-cut, basutförande","sort_order":10},{"param_key":"mounting","code":"FZ","label":"Boss-cut, fläns vid kolvstången","sort_order":11},{"param_key":"mounting","code":"UZ","label":"Boss-cut, tappfäste vid kolvstången","sort_order":12},{"param_key":"magnet","code":"D","label":"Inbyggd magnet för givare (CDM2)","sort_order":0},{"param_key":"port","code":"TN","label":"Portgänga NPT (standard är Rc)","sort_order":0},{"param_key":"port","code":"TF","label":"Portgänga G (standard är Rc)","sort_order":1},{"param_key":"cushion","code":"A","label":"Luftdämpning (standard är gummidämpning)","sort_order":0},{"param_key":"rod_thread","code":"F","label":"Honstång (invändig gänga; utan bälg och tillbehör)","sort_order":0},{"param_key":"boot","code":"J","label":"Bälg i nylonduk, max 70 °C","sort_order":0},{"param_key":"boot","code":"K","label":"Värmebeständig bälg, max 110 °C","sort_order":1},{"param_key":"pivot","code":"N","label":"Pivotfäste medlevererat (bara fäste C, T, U, E, V, UZ)","sort_order":0},{"param_key":"rod_end","code":"V","label":"Enkel knäled (utan sprint)","sort_order":0},{"param_key":"rod_end","code":"W","label":"Dubbel knäled","sort_order":1},{"param_key":"rod_end","code":"Q","label":"Kolvstångsände (rod end)","sort_order":2},{"param_key":"switch","code":"M9N","label":"D-M9N, 3-tråd NPN, rak","sort_order":0},{"param_key":"switch","code":"M9P","label":"D-M9P, 3-tråd PNP, rak","sort_order":1},{"param_key":"switch","code":"M9B","label":"D-M9B, 2-tråd, rak","sort_order":2},{"param_key":"switch","code":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad","sort_order":3},{"param_key":"switch","code":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad","sort_order":4},{"param_key":"switch","code":"M9BV","label":"D-M9BV, 2-tråd, vinklad","sort_order":5},{"param_key":"switch","code":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak","sort_order":6},{"param_key":"switch","code":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak","sort_order":7},{"param_key":"switch","code":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak","sort_order":8},{"param_key":"switch","code":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad","sort_order":9},{"param_key":"switch","code":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad","sort_order":10},{"param_key":"switch","code":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad","sort_order":11},{"param_key":"switch","code":"M9NA","label":"D-M9NA, NPN, vattentät, rak","sort_order":12},{"param_key":"switch","code":"M9PA","label":"D-M9PA, PNP, vattentät, rak","sort_order":13},{"param_key":"switch","code":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak","sort_order":14},{"param_key":"switch","code":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad","sort_order":15},{"param_key":"switch","code":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad","sort_order":16},{"param_key":"switch","code":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad","sort_order":17},{"param_key":"switch","code":"A96","label":"D-A96, reed 3-tråd, rak","sort_order":18},{"param_key":"switch","code":"A96V","label":"D-A96V, reed 3-tråd, vinklad","sort_order":19},{"param_key":"switch","code":"A93","label":"D-A93, reed 2-tråd, rak","sort_order":20},{"param_key":"switch","code":"A93V","label":"D-A93V, reed 2-tråd, vinklad","sort_order":21},{"param_key":"switch","code":"A90","label":"D-A90, reed utan indikering, rak","sort_order":22},{"param_key":"switch","code":"A90V","label":"D-A90V, reed utan indikering, vinklad","sort_order":23},{"param_key":"lead","code":"M","label":"1 m kabel","sort_order":0},{"param_key":"lead","code":"L","label":"3 m kabel","sort_order":1},{"param_key":"lead","code":"Z","label":"5 m kabel","sort_order":2},{"param_key":"count","code":"S","label":"1 givare (standard är 2)","sort_order":0},{"param_key":"mto","code":"XB6","label":"-XB6 Värmebeständig –10…150 °C (utan givare)","sort_order":0},{"param_key":"mto","code":"XB7","label":"-XB7 Köldbeständig –40…70 °C (utan givare, gummidämpning)","sort_order":1},{"param_key":"mto","code":"XB9","label":"-XB9 Låg hastighet 10–50 mm/s (gummidämpning; luft på begäran)","sort_order":2},{"param_key":"mto","code":"XC3","label":"-XC3 Speciell portplacering","sort_order":3},{"param_key":"mto","code":"XC4A","label":"-XC4A Dammtålig med två smörjhållare (gummidämpning, utan bälg)","sort_order":4},{"param_key":"mto","code":"XC4B","label":"-XC4B Dammtålig med smörjhållare och kraftig avstrykare (gummidämpning, utan bälg)","sort_order":5},{"param_key":"mto","code":"XC4C","label":"-XC4C Dammtålig med kraftig avstrykare (utan bälg)","sort_order":6},{"param_key":"mto","code":"XC6A","label":"-XC6A Rostfri kolvstång och stångmutter (slag ≤ 1000)","sort_order":7},{"param_key":"mto","code":"XC6B","label":"-XC6B Rostfri kolvstång, muttrar, låsring och fäste (slag ≤ 1000; ej gaffel-/tappfäste)","sort_order":8},{"param_key":"mto","code":"XC29","label":"-XC29 Dubbel knäled med fjädersprint (kräver tillbehör W)","sort_order":9},{"param_key":"mto","code":"XC52","label":"-XC52 Fästmutter med stoppskruv (fäste B, L, F, G, BZ, FZ)","sort_order":10},{"param_key":"mto","code":"XC85","label":"-XC85 Fett för livsmedelsindustrin","sort_order":11},{"param_key":"mto","code":"X446","label":"-X446 PTFE-fett","sort_order":12}]'::jsonb)
