delete from config_rules where schema_id = 'SCHEMA-CM2-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-CM2-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"rod_thread"},"F"]},{"in":[{"var":"boot"},["J","K"]]}]},"message_sv":"Honstång F levereras utan bälg (sida 5).","message_en":"The female rod end F ships without a rod boot (page 5).","goto_step":"cm2-boot"},{"severity":"error","if_json":{"and":[{"==":[{"var":"rod_thread"},"F"]},{"in":[{"var":"rod_end"},["V","W","Q"]]}]},"message_sv":"Kolvstångstillbehör (V/W/Q) finns inte för honstången F (sida 5).","message_en":"No rod end bracket (V/W/Q) is provided for the female rod end F (page 5).","goto_step":"cm2-rod_end"},{"severity":"error","if_json":{"and":[{"==":[{"var":"pivot"},"N"]},{"in":[{"var":"mounting"},["B","L","F","G","D","BZ","FZ"]]}]},"message_sv":"Pivotfästet N finns bara för fäste C, U, T, E, V och UZ (sida 5).","message_en":"The pivot bracket N exists only for mounting C, U, T, E, V and UZ (page 5).","goto_step":"cm2-pivot"},{"severity":"error","if_json":{"and":[{"in":[{"var":"boot"},["J","K"]]},{">":[{"var":"stroke_mm"},1000]}]},"message_sv":"Med bälg är största slag 1000 mm (sida 6, not 3).","message_en":"With a rod boot the maximum stroke is 1000 mm (page 6, note 3).","goto_step":"cm2-stroke_mm"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"!=":[{"var":"magnet"},"D"]}]},"message_sv":"En givare kräver magnetcylindern CDM2 — välj inbyggd magnet (sida 5).","message_en":"An auto switch needs the CDM2 magnet cylinder — choose the built-in magnet (page 5).","goto_step":"cm2-magnet"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch"},""]},{"or":[{"!=":[{"var":"lead"},""]},{"!=":[{"var":"count"},""]}]}]},"message_sv":"Kabellängd och antal hör till givaren — välj en givare först.","message_en":"Lead wire length and quantity belong to the auto switch — choose a switch first.","goto_step":"cm2-switch"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"lead"},""]},{"in":[{"var":"switch"},["M9NA","M9PA","M9BA","M9NAV","M9PAV","M9BAV"]]}]},"message_sv":"